WITH metrics AS (SELECT *, CORR(humidity, pressure) OVER (PARTITION BY device_code) corr_humidity_pressure, SUM(temp_c) OVER (PARTITION BY device_code ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_temp_c FROM device_readings) SELECT id, device_code, reading_ts, temp_c, pressure, status_bits, firmware, corr_humidity_pressure FROM metrics ORDER BY firmware DESC
